fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows in the input matrix
    let rows = arr.len();
    // Number of columns in the input matrix (assume non-empty and rectangular)
    let cols = arr[0].len();

    // Initialize the output matrix with dimensions cols x rows
    // Each vector in output has 'rows' elements
    let mut transposed = vec![vec![0i8; rows]; cols];

    // Fill the transposed matrix such that transposed[j][i] = arr[i][j]
    for i in 0..rows {
        for j in 0..cols {
            transposed[j][i] = arr[i][j];
        }
    }

    transposed
}